/** @param {string} name @param {string} [cls] @param {'md' | 'xs'} [size] a menü 20 px-es vagy a 12 px-es glifája */
export const icon = (name, cls = 'ic', size = undefined) => `<svg class="${cls}" viewBox="0 0 16 16" aria-hidden="true">${glyph(name, size)}</svg>`;
// Fájltípus-ikon: a git-graph a fájlhoz rendelt Catppuccin-ikon SVG-jét adja
// (`fileIcons`, a színei a lap `--ic-*` tokenjei); ha a készlet hiányzik, az általános ikon.
export const fileIcon = f => {
  const svg = DATA.fileIcons?.[f.icon];
  return svg ? svg.replace('<svg', '<svg class="fic" aria-hidden="true"') : icon('file', 'ic fic');
};

/** @param {string} name @param {string} color @param {'md' | 'xs'} [size] */
export const tinted = (name, color, size = undefined) => `<svg class="ic" style="color:${color}" viewBox="0 0 16 16" aria-hidden="true">${glyph(name, size)}</svg>`;
